arguments.command:
python3 -c "
import json
with open('/app/resources/treasury_bulletin_1942_10.json', 'r') as f:
    data = json.load(f)
# Print keys at top level
def print_structure(d, indent=0):
    if isinstance(d, dict):
        for k, v in d.items():
            print('  ' * indent + str(k))
            if isinstance(v, dict) and indent < 2:
                print_structure(v, indent + 1)
            elif isinstance(v, list) and indent < 2 and len(v) > 0:
                print('  ' * (indent+1) + f'List of {len(v)} items')
print_structure(data)
"
